// タスク API を MockMvc で叩いてみる(Web サーバーは起動しない)
// ここを変えてみよう:title を変える / POST を増やす / 存在しない ID を GET する
import static java.nio.charset.StandardCharsets.UTF_8;
import java.util.concurrent.atomic.AtomicLong;
import org.springframework.http.*;
import org.springframework.http.converter.*;
import org.springframework.http.converter.json.*;
import org.springframework.web.bind.annotation.*;
import org.springframework.test.web.servlet.*;
import org.springframework.test.web.servlet.setup.*;
import static org.springframework.test.web.servlet
        .request.MockMvcRequestBuilders.*;

record Task(long id, String title, boolean done) {}
record CreateTaskRequest(String title) {}

@RestController
@RequestMapping("/api/tasks")
class TaskController {
    private final Map<Long, Task> store = new TreeMap<>();
    private final AtomicLong seq = new AtomicLong();

    @GetMapping
    List<Task> list() {
        return List.copyOf(store.values());
    }

    @GetMapping("/{id}")
    ResponseEntity<Task> get(@PathVariable long id) {
        return ResponseEntity.of(Optional.ofNullable(store.get(id)));
    }

    @PostMapping
    ResponseEntity<Task> create(@RequestBody CreateTaskRequest req) {
        long id = seq.incrementAndGet();
        Task t = new Task(id, req.title(), false);
        store.put(id, t);
        URI location = URI.create("/api/tasks/" + id);
        return ResponseEntity.created(location).body(t);
    }
}

MockMvc mvc = MockMvcBuilders.standaloneSetup(new TaskController())
    .setMessageConverters(new StringHttpMessageConverter(UTF_8),
                          new MappingJackson2HttpMessageConverter())
    .defaultResponseCharacterEncoding(UTF_8)
    .build();

void show(String label, MvcResult r) throws Exception {
    var res = r.getResponse();
    String loc = res.getHeader("Location");
    System.out.println("■ " + label);
    System.out.println("  " + res.getStatus()
        + (loc == null ? "" : "  Location: " + loc)
        + "  本文: " + res.getContentAsString());
}

show("POST /api/tasks", mvc.perform(post("/api/tasks")
    .contentType(MediaType.APPLICATION_JSON)
    .content("{\"title\":\"請求書を送る\"}")).andReturn());
show("GET /api/tasks", mvc.perform(get("/api/tasks")).andReturn());
show("GET /api/tasks/1", mvc.perform(get("/api/tasks/1")).andReturn());
show("GET /api/tasks/99", mvc.perform(get("/api/tasks/99")).andReturn());

// Content-Type を付け忘れると……?(curl の -d だけで送ったときと同じ)
show("POST(Content-Type なし)", mvc.perform(post("/api/tasks")
    .content("{\"title\":\"x\"}")).andReturn());

// Jackson で record ⇔ JSON。LocalDate の扱いに注目
// ここを変えてみよう:日付や title を変える / ④の JSON に "x":1 を足してみる
import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.SerializationFeature;
import com.fasterxml.jackson.datatype.jsr310.JavaTimeModule;

record TaskResponse(long id, String title, LocalDate dueDate) {}

TaskResponse task = new TaskResponse(1, "見積書を作る", LocalDate.of(2026, 10, 31));

// ① 素の ObjectMapper:java.time に対応していないので失敗する
try {
    System.out.println(new ObjectMapper().writeValueAsString(task));
} catch (Exception e) {
    String first = e.getMessage().lines().findFirst().orElse("");
    System.out.println("① 失敗: " + first);
}

// ② JavaTimeModule を登録:変換できるが、日付が配列になる
ObjectMapper m2 = new ObjectMapper().registerModule(new JavaTimeModule());
System.out.println("② " + m2.writeValueAsString(task));

// ③ さらに日時を「数値」で書く設定を切る → ISO-8601 の文字列(Spring Boot の既定)
ObjectMapper m3 = new ObjectMapper().registerModule(new JavaTimeModule())
    .disable(SerializationFeature.WRITE_DATES_AS_TIMESTAMPS);
System.out.println("③ " + m3.writeValueAsString(task));

// ④ 逆向き:JSON → record(正準コンストラクタで作られる)
// 知らない項目 "x":1 を足すと、素の ObjectMapper は UnrecognizedPropertyException
// (Spring が作る ObjectMapper は、知らない項目を無視する設定になっている)
String json = "{\"id\":2,\"title\":\"請求書を送る\",\"dueDate\":\"2026-11-05\"}";
TaskResponse back = m3.readValue(json, TaskResponse.class);
System.out.println("④ " + back);

