    // 本物のアプリなら DB。ここではメモリ上の Map(TreeMap なので商品コード順)
    private final Map<String, Item> items = new TreeMap<>();

    public InventoryController() {
        put(new Item("A-001", "ボールペン", 120));
        put(new Item("A-002", "ノート", 0));
        put(new Item("B-010", "クリアファイル", 35));
